/**
 * The frame: a poster generated by the garden, over a sky that keeps the
 * real time of day. Every bird BirdFrame heard this hour owns a block sized
 * by its calls and coloured by its own portrait; the house sits in fixed
 * blocks above and below. It may dramatise; it may not fabricate. The
 * journal is one tap away.
 */

import { useCallback, useMemo, useState, type CSSProperties } from "react";
import { agendaFor, type HubEvent } from "../../lib/frame/agenda.ts";
import type { FrameConfig } from "../../lib/frame/config.ts";
import { GOLD, groundPalette, typeInkFor } from "../../lib/frame/palette.ts";
import { usePortraits } from "../../lib/frame/portraits.ts";
import { composeField, type PosterField } from "../../lib/frame/poster.ts";
import { bloomIsLeaving, nextBloom, quietFor } from "../../lib/frame/scene.ts";
import {
  daylightLabel,
  mixRgb,
  moonIllumination,
  moonPosition,
  rgbCss,
  skyPalette,
  sunIsRising,
  sunPosition,
  sunTimes,
  type Rgb,
} from "../../lib/frame/solar.ts";
import type { BirdframeStream } from "../../lib/frame/stream.ts";
import type { BirdVoices } from "../../lib/frame/voices.ts";
import { parseForecast, weatherMood, type HubWeather } from "../../lib/frame/weather.ts";
import { Poster, type HouseholdPanel } from "./Poster.tsx";
import { Sky } from "./Sky.tsx";
import "./frame.css";

export { typeInkFor };

export type FrameMode = "frame" | "home" | "conversation";

/** What the household hub gives the board; the launcher's hub type is a superset. */
export type FrameHub = {
  weather: HubWeather | null;
  forecast?: unknown;
  events?: HubEvent[];
};

type FrameProps = {
  now: number;
  config: FrameConfig;
  stream: BirdframeStream;
  hub: FrameHub | null;
  shoppingCount: number;
  mode: FrameMode;
  voices: BirdVoices;
  onOpenJournal: () => void;
  onOpenHousehold: (panel?: HouseholdPanel) => void;
};

const GROUND_DAY: Rgb = [236, 233, 222];
const GROUND_NIGHT: Rgb = [22, 26, 44];
const CLOUD_DAY: Rgb = [251, 248, 239];
const CLOUD_NIGHT: Rgb = [46, 52, 84];
const INK_DAY: Rgb = [22, 42, 36];
const INK_NIGHT: Rgb = [9, 11, 24];
const PULSE_MS = 3_000;
const EMPTY_FIELD: PosterField = { window: "hour", blocks: [] };
const NO_KEYS: ReadonlySet<string> = new Set();

export function Frame({
  now,
  config,
  stream,
  hub,
  shoppingCount,
  mode,
  voices,
  onOpenJournal,
  onOpenHousehold,
}: FrameProps) {
  const { snapshot, reachable, heartbeat } = stream;
  // Hearing a bird: its own recording through the Pi's speaker, shared with home.
  const { playing, hear } = voices;
  const paletteTick = Math.floor(now / 5_000) * 5_000;
  const minuteTick = Math.floor(now / 60_000) * 60_000;
  const weather = hub?.weather ?? null;

  const sun = useMemo(
    () => sunPosition(paletteTick, config.latitude, config.longitude),
    [paletteTick, config.latitude, config.longitude],
  );
  const moon = useMemo(
    () => moonPosition(paletteTick, config.latitude, config.longitude),
    [paletteTick, config.latitude, config.longitude],
  );
  const illumination = useMemo(() => moonIllumination(paletteTick), [paletteTick]);
  const rising = useMemo(
    () => sunIsRising(paletteTick, config.latitude, config.longitude),
    [paletteTick, config.latitude, config.longitude],
  );
  const palette = useMemo(() => skyPalette(sun.elevation, rising), [sun.elevation, rising]);
  const ground = useMemo(() => groundPalette(palette, rising), [palette, rising]);
  const times = useMemo(
    () => sunTimes(paletteTick, config.latitude, config.longitude),
    [paletteTick, config.latitude, config.longitude],
  );
  const mood = useMemo(() => weatherMood(weather, config.facing), [weather, config.facing]);
  const forecast = useMemo(() => parseForecast(hub?.forecast), [hub?.forecast]);
  const agenda = useMemo(() => agendaFor(hub?.events, minuteTick), [hub?.events, minuteTick]);
  const isNight = sun.elevation < -6;

  // The field: when the snapshot changes and otherwise once a minute, from
  // the last field, so blocks grow and shrink in place rather than being
  // dealt afresh, and nothing on the wall moves between events. The
  // previous field is state adjusted during render, the React-sanctioned
  // way to carry one render's result into the next.
  const [fieldState, setFieldState] = useState<{
    snapshot: BirdframeStream["snapshot"];
    tick: number;
    field: PosterField;
    keys: Set<string>;
    born: ReadonlySet<string>;
  }>({ snapshot: null, tick: 0, field: EMPTY_FIELD, keys: new Set(), born: NO_KEYS });
  if (fieldState.snapshot !== snapshot || fieldState.tick !== minuteTick) {
    const next = snapshot ? composeField(snapshot, minuteTick, fieldState.field) : EMPTY_FIELD;
    const keys = new Set(next.blocks.map((block) => block.key));
    const born = new Set<string>();
    if (fieldState.tick) for (const key of keys) if (!fieldState.keys.has(key)) born.add(key);
    setFieldState({ snapshot, tick: minuteTick, field: next, keys, born });
  }
  const { field, born: bornKeys } = fieldState;

  // The bloom: what, if anything, is having its moment, as a pure function of
  // the snapshot and the clock. Its species rings once per call.
  const bloomNow = useMemo(() => (snapshot ? nextBloom(snapshot, { now }) : null), [snapshot, now]);
  const bloom = bloomNow && !bloomIsLeaving(bloomNow, now) ? bloomNow : null;
  const bloomId = bloom?.detectionId ?? 0;
  const bloomName = bloom?.commonName ?? "";
  const [arrivals, setArrivals] = useState<ReadonlyMap<string, number>>(new Map());
  if (bloomId && bloomName && arrivals.get(bloomName) !== bloomId) {
    const map = new Map(arrivals);
    map.set(bloomName, bloomId);
    setArrivals(map);
  }

  // The listening pulse: a ring every time the bridge hears from BirdFrame.
  const pulsing = reachable && heartbeat > 0 && now - heartbeat < PULSE_MS;

  const portraitNames = useMemo(() => {
    const names = new Set<string>();
    for (const block of field.blocks) {
      if (block.kind === "bird" && block.species.scientificName) names.add(block.species.scientificName);
    }
    return [...names];
  }, [field]);
  const portraits = usePortraits(portraitNames);

  const bloomClip = bloom?.clipUrl ?? null;
  const onHear = useCallback(
    (commonName: string) => hear(commonName, commonName === bloomName ? bloomClip : null),
    [hear, bloomName, bloomClip],
  );

  const ink = mixRgb(INK_DAY, INK_NIGHT, palette.darkness);
  const style = {
    "--frame-zenith": rgbCss(palette.zenith),
    "--frame-mid": rgbCss(palette.mid),
    "--frame-horizon": rgbCss(palette.horizon),
    "--frame-glow": rgbCss(palette.glow),
    "--frame-lawn": rgbCss(mixRgb(GROUND_DAY, GROUND_NIGHT, palette.darkness)),
    "--frame-cloud": rgbCss(mixRgb(CLOUD_DAY, CLOUD_NIGHT, palette.darkness)),
    "--frame-ink-rgb": ink.join(" "),
    "--frame-type-rgb": ground.type.join(" "),
    "--frame-paper-rgb": ground.paper.join(" "),
    "--frame-paper-deep-rgb": ground.paperDeep.join(" "),
    "--frame-gold-rgb": GOLD.join(" "),
    "--frame-darkness": String(palette.darkness),
  } as CSSProperties;

  const daylight = daylightLabel(now, times);
  const quietMs = quietFor(snapshot, minuteTick);

  return (
    <div className="frame" data-mode={mode} data-night={isNight} style={style} aria-hidden={mode !== "frame"}>
      <div className="frame__painting">
        <Sky tick={paletteTick} palette={palette} sun={sun} moon={moon} illumination={illumination} mood={mood} facing={config.facing} />
        <div className="frame-wash" />
        {pulsing ? <div className="frame-pulse" key={heartbeat} /> : null}
        {!reachable && snapshot ? <div className="frame-unreachable" /> : null}
        <div className="frame-grain" />
      </div>
      <div className="frame__veil" />
      <div className="frame__chrome">
        {/* Under the home pages the poster is hidden, so its clock keeps minute time and nothing re-renders each second. */}
        <Poster
          now={mode === "frame" ? now : minuteTick}
          minuteTick={minuteTick}
          field={field}
          bornKeys={bornKeys}
          arrivals={arrivals}
          portraits={portraits}
          ground={ground}
          night={isNight}
          place={config.place}
          daylight={daylight}
          reachable={reachable}
          todayCount={snapshot ? snapshot.todaySpeciesCount : null}
          quietMinutes={quietMs === null ? null : Math.round(quietMs / 60_000)}
          weather={weather}
          forecast={forecast}
          agenda={agenda}
          shoppingCount={shoppingCount}
          playing={playing}
          onHear={onHear}
          onOpenJournal={onOpenJournal}
          onOpenHousehold={onOpenHousehold}
        />
      </div>
    </div>
  );
}
